record.field:
{
    "type": "object",
    "properties": {
        "query": {
            "type": "string",
            "description": "Customer name, phone number or email address."
        }
    },
    "required": ["query"]
}

{
    "type": "object",
    "properties": {
        "serial_number": {
            "type": "string",
            "description": "Serial number printed on the camera label."
        }
    },
    "required": ["serial_number"]
}

{
    "type": "object",
    "properties": {
        "customer": {"type": "string", "description": "Customer name."},
        "city": {"type": "string", "description": "City of the installation site."},
        "date": {"type": "string", "description": "Requested date, ISO 8601 (YYYY-MM-DD)."},
        "issue": {"type": "string", "description": "Short description of the reported issue."}
    },
    "required": ["customer", "date"]
}
